// GENERATED by "npm run sync:cocos" from packages/game-logic/src/controllers/debugController.ts. Do not edit here.
import { buyPriceX, payScale } from '../../math-core/index';
import type { ConfigOverrides, GameConfig } from '../../math-core/index';
import { Observable } from '../core/observable';
import type { ReadOnlyObservable } from '../core/observable';
import type { LocalGame } from '../createLocalGame';

export type MultiplierVariant = 'A' | 'B' | 'C' | 'D';
export const VARIANTS: readonly MultiplierVariant[] = ['A', 'B', 'C', 'D'];

/** A number the debug panel can change. One row in the panel per entry. */
export type DebugField = 'goldenBase' | 'goldenFree' | 'freeSpins' | 'buyPrice' | 'maxWin';
export interface DebugFieldSpec { field: DebugField; label: string; step: number; min: number }

export const DEBUG_FIELDS: readonly DebugFieldSpec[] = [
  { field: 'goldenBase', label: 'Golden chance (base)', step: 0.01, min: 0 },
  { field: 'goldenFree', label: 'Golden chance (free)', step: 0.01, min: 0 },
  { field: 'freeSpins', label: 'Free spins awarded', step: 1, min: 1 },
  { field: 'buyPrice', label: 'Buy price (x bet)', step: 1, min: 1 },
  { field: 'maxWin', label: 'Max win (x bet)', step: 100, min: 100 },
];

export interface DebugStats { rounds: number; cost: number; win: number; freeSpinRounds: number; biggestX: number }
export interface DebugMessage { text: string; bad: boolean }

const emptyStats = (): DebugStats => ({ rounds: 0, cost: 0, win: 0, freeSpinRounds: 0, biggestX: 0 });

/**
 * The logic behind the debug panel (feature 19), with no screen code, so the HTML and Cocos panels share it.
 * Everything here is session only: overrides live in memory in the config service and vanish on reload.
 */
export class DebugController {
  readonly stats = new Observable<DebugStats>(emptyStats());
  readonly message = new Observable<DebugMessage>({ text: '', bad: false });

  constructor(private readonly game: LocalGame) {
    game.bus.on('spinResolved', e => {
      const s = this.stats.value;
      this.stats.set({
        rounds: s.rounds + 1, cost: s.cost + e.result.cost, win: s.win + e.result.totalWin,
        freeSpinRounds: s.freeSpinRounds + (e.result.freeSpins ? 1 : 0), biggestX: Math.max(s.biggestX, e.result.winX),
      });
    });
  }

  get config(): ReadOnlyObservable<GameConfig> { return this.game.services.config.config; }
  get overridesActive(): boolean { return this.game.services.config.changed.length > 0; }

  get(field: DebugField): number {
    const c = this.config.value;
    switch (field) {
      case 'goldenBase': return c.golden.chanceBase;
      case 'goldenFree': return c.golden.chanceFree;
      case 'freeSpins': return c.freeSpins.spins;
      case 'buyPrice': return buyPriceX(c);
      case 'maxWin': return c.maxWinX;
    }
  }

  /** Sets a number. Returns false (and says why) if the value is not valid. */
  set(field: DebugField, value: number): boolean {
    const spec = DEBUG_FIELDS.find(f => f.field === field)!;
    const v = Math.round(Math.max(spec.min, value) * 1e6) / 1e6;
    const variant = this.config.value.multiplier.variant;
    const patch: ConfigOverrides = {
      goldenBase: { golden: { chanceBase: v } },
      goldenFree: { golden: { chanceFree: v } },
      freeSpins: { freeSpins: { spins: v } },
      buyPrice: { buyBonus: { priceXByVariant: { [variant]: v } } },
      maxWin: { maxWinX: v },
    }[field] as ConfigOverrides;
    return this.apply(patch);
  }

  /** Steps a number up or down by its step size. */
  nudge(field: DebugField, direction: 1 | -1): boolean {
    const spec = DEBUG_FIELDS.find(f => f.field === field)!;
    return this.set(field, this.get(field) + direction * spec.step);
  }

  setVariant(variant: MultiplierVariant): boolean { return this.apply({ multiplier: { variant } } as ConfigOverrides); }

  /** Next variant in A, B, C, D order, wrapping around. */
  cycleVariant(): boolean {
    const i = VARIANTS.indexOf(this.config.value.multiplier.variant);
    return this.setVariant(VARIANTS[(i + 1) % VARIANTS.length]!);
  }

  clearOverrides(): void {
    this.game.services.config.clearOverrides();
    this.say('Overrides cleared');
  }

  exportOverrides(): string { return this.game.services.config.exportOverrides(); }

  /** The next spin triggers free spins (the local service only allows this in debug builds). */
  forceFreeSpins(): void {
    this.game.controllers.spin.forceNext({ triggerFreeSpins: true });
    this.say('Next spin triggers free spins');
  }

  async buyBonusNow(): Promise<void> {
    await this.game.controllers.buyBonus.buy(1);
  }

  /** Sets the demo balance. Refused while a round is running or for a negative amount. */
  setBalance(amount: number): boolean {
    if (!(amount >= 0) || this.game.models.spin.isBusy) { this.say('Balance not changed (round running or invalid)', true); return false; }
    const wallet = this.game.services.wallet;
    wallet.apply(amount - wallet.peek());
    this.game.models.wallet.balance.set(wallet.peek());
    this.say(`Balance set to ${amount.toFixed(2)}`);
    return true;
  }

  setLatency(ms: number): void { this.game.services.spin.setLatency(ms); }
  setOffline(offline: boolean): void {
    this.game.services.spin.setOffline(offline);
    this.say(offline ? 'Next spins fail: offline' : 'Back online');
  }

  resetStats(): void { this.stats.set(emptyStats()); }

  sessionRtp(): number | undefined {
    const s = this.stats.value;
    return s.cost > 0 ? s.win / s.cost : undefined;
  }

  /** What the selected multiplier variant does, in plain words, with the live numbers from the config. */
  describeVariant(c: GameConfig = this.config.value): string {
    const m = c.multiplier;
    const ladder = (l: number[]): string => l.map(x => `x${x}`).join(' ');
    const money = `Pay scale x${payScale(c)}, buy price ${buyPriceX(c)}x bet.`;
    switch (m.variant) {
      case 'A': return `A. Fixed ladder. Every cascade in a spin goes one step up: base ${ladder(m.A.base)}, free spins ${ladder(m.A.free)}. The last step repeats. It resets at the start of every spin. ${money}`;
      case 'B': return `B. Endless. Base starts at x${m.B.base.start} and adds +${m.B.base.step} per cascade; free spins start at x${m.B.free.start} and add +${m.B.free.step}. No upper limit. It resets every spin. ${money}`;
      case 'C': return `C. Like A, but in free spins the ladder does not reset between spins, it keeps climbing through the whole feature (base ${ladder(m.C.base)}, free ${ladder(m.C.free)}). Base spins reset as in A. ${money}`;
      case 'D': return `D. Multiplier spots. A card that takes part in a win marks its cell. Each later win on a marked cell doubles it (x2, x4, x8 up to x${m.D.cap}). A win's multiplier is the sum of the spots under its cards, at least x1. Spots reset every base spin and ${m.D.persistInFree === false ? 'every free spin' : 'last through the whole free spins feature'}. ${money}`;
    }
  }

  private apply(patch: ConfigOverrides): boolean {
    const svc = this.game.services.config;
    try {
      svc.setOverrides(mergeDeep(structuredClone(svc.overrides), patch));
      this.say(`Changed: ${svc.changed.join(', ') || 'nothing'}`);
      return true;
    } catch (e) {
      this.say(e instanceof Error ? e.message : String(e), true);
      return false;
    }
  }

  private say(text: string, bad = false): void { this.message.set({ text, bad }); }
}

function mergeDeep<T>(a: T, b: unknown): T {
  if (typeof b !== 'object' || b === null || Array.isArray(b)) return b as T;
  const out = (typeof a === 'object' && a !== null ? a : {}) as Record<string, unknown>;
  for (const k of Object.keys(b)) out[k] = mergeDeep(out[k], (b as Record<string, unknown>)[k]);
  return out as T;
}
